                        seen.add((ny, nx))
                        stack.append((ny, nx))

            if len(component) != 1:
                continue

            y, x = component[0]
            counts = Counter()
            for ny in range(max(0, y - 2), min(h, y + 3)):
                for nx in range(max(0, x - 2), min(w, x + 3)):
